 for j,c in enumerate(combos):rows.append(dict(arm_centre_mm=pos,arm_width_mm=width,force_per_cup_N=c[0],assumed_E_MPa=c[1],exponent=c[2],cover_parallel_N_mm3=c[3],protrusion_mm=c[4],whole_pad_modulus_ratio=c[5],local_pressure_change_percent=local[j],peak_pressure_change_percent=peak[j],max_compression_fraction=soft['compression'][j],within_chosen_compression_range=bool(eligible[j]),detached_fraction=soft['detached'][j]))
